#include <stdio.h>

/* ── 头一份：只留这一行宣告 ── */
int add(int a, int b);

/* ── 身子留一份就够了 ── */
int add(int a, int b) {
    return a + b;
}

int main(void) {
    printf("结果 %d\n", add({a}, {b}));
    return 0;
}
